:- module(m__eu_nis2_information_sharing_voluntary_notification_fixtures, [nis2_information_sharing_voluntary_notification_subject/1, nis2_information_sharing_voluntary_notification_profile_for/2, nis2_information_sharing_voluntary_notification_assess/2]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).
:- use_module(m__eu_nis2_information_sharing_voluntary_notification_nis2_information_sharing_voluntary_notification, [decide_nis2_information_sharing_voluntary_notification/2]).

nis2_information_sharing_voluntary_notification_subject(essential_entity_notifying_an_incident).
nis2_information_sharing_voluntary_notification_subject(other_entity_notifying_an_incident).
nis2_information_sharing_voluntary_notification_subject(other_entity_notifying_a_significant_incident).
nis2_information_sharing_voluntary_notification_subject(unclassified_entity_notifying_a_cyber_threat).
nis2_information_sharing_voluntary_notification_subject(unclassified_entity_notifying_an_incident).
nis2_information_sharing_voluntary_notification_subject(exchange_aiming_at_response).
nis2_information_sharing_voluntary_notification_subject(exchange_meeting_neither_point).
nis2_information_sharing_voluntary_notification_subject(exchange_enhancing_cybersecurity_only).
nis2_information_sharing_voluntary_notification_subject(exchange_of_irrelevant_information).
nis2_information_sharing_voluntary_notification_subject(exchange_with_unsure_relevance).
nis2_information_sharing_voluntary_notification_subject(exchange_with_unsure_relevance_and_no_points).
nis2_information_sharing_voluntary_notification_subject(essential_entity_entering_an_arrangement).
nis2_information_sharing_voluntary_notification_subject(other_entity_entering_an_arrangement).
nis2_information_sharing_voluntary_notification_subject(important_entity_withdrawing_from_an_arrangement).
nis2_information_sharing_voluntary_notification_subject(important_entity_withdrawing_from_an_informal_contact).
nis2_information_sharing_voluntary_notification_subject(essential_entity_entering_an_unsure_arrangement).
nis2_information_sharing_voluntary_notification_subject(essential_entity_with_an_unsure_arrangement_and_no_event).
nis2_information_sharing_voluntary_notification_subject(profile_with_an_untyped_key).
nis2_information_sharing_voluntary_notification_subject(empty_profile).

nis2_information_sharing_voluntary_notification_profile_for(essential_entity_notifying_an_incident, [attribute(entity_class, essential_entity), attribute(event_kind, incident)]).
nis2_information_sharing_voluntary_notification_profile_for(other_entity_notifying_an_incident, [attribute(entity_class, out_of_scope), attribute(event_kind, incident)]).
nis2_information_sharing_voluntary_notification_profile_for(other_entity_notifying_a_significant_incident, [attribute(entity_class, out_of_scope), attribute(event_kind, significant_incident)]).
nis2_information_sharing_voluntary_notification_profile_for(unclassified_entity_notifying_a_cyber_threat, [attribute(event_kind, cyber_threat)]).
nis2_information_sharing_voluntary_notification_profile_for(unclassified_entity_notifying_an_incident, [attribute(event_kind, incident)]).
nis2_information_sharing_voluntary_notification_profile_for(exchange_aiming_at_response, [attribute(information_is_relevant_cybersecurity_information, true), attribute(sharing_aims_to_prevent_detect_respond_to_or_recover_from_incidents_or_mitigate_their_impact, true)]).
nis2_information_sharing_voluntary_notification_profile_for(exchange_meeting_neither_point, [attribute(information_is_relevant_cybersecurity_information, true), attribute(sharing_aims_to_prevent_detect_respond_to_or_recover_from_incidents_or_mitigate_their_impact, false), attribute(sharing_enhances_the_level_of_cybersecurity, false)]).
nis2_information_sharing_voluntary_notification_profile_for(exchange_enhancing_cybersecurity_only, [attribute(information_is_relevant_cybersecurity_information, true), attribute(sharing_aims_to_prevent_detect_respond_to_or_recover_from_incidents_or_mitigate_their_impact, false), attribute(sharing_enhances_the_level_of_cybersecurity, true)]).
nis2_information_sharing_voluntary_notification_profile_for(exchange_of_irrelevant_information, [attribute(information_is_relevant_cybersecurity_information, false), attribute(sharing_aims_to_prevent_detect_respond_to_or_recover_from_incidents_or_mitigate_their_impact, false), attribute(sharing_enhances_the_level_of_cybersecurity, true)]).
nis2_information_sharing_voluntary_notification_profile_for(exchange_with_unsure_relevance, [attribute(information_is_relevant_cybersecurity_information, unsure), attribute(sharing_aims_to_prevent_detect_respond_to_or_recover_from_incidents_or_mitigate_their_impact, true)]).
nis2_information_sharing_voluntary_notification_profile_for(exchange_with_unsure_relevance_and_no_points, [attribute(information_is_relevant_cybersecurity_information, unsure)]).
nis2_information_sharing_voluntary_notification_profile_for(essential_entity_entering_an_arrangement, [attribute(entity_class, essential_entity), attribute(arrangement_event, entered), attribute(arrangement_is_a_cybersecurity_information_sharing_arrangement, true)]).
nis2_information_sharing_voluntary_notification_profile_for(other_entity_entering_an_arrangement, [attribute(entity_class, out_of_scope), attribute(arrangement_event, entered), attribute(arrangement_is_a_cybersecurity_information_sharing_arrangement, true)]).
nis2_information_sharing_voluntary_notification_profile_for(important_entity_withdrawing_from_an_arrangement, [attribute(entity_class, important_entity), attribute(arrangement_event, withdrew), attribute(arrangement_is_a_cybersecurity_information_sharing_arrangement, true)]).
nis2_information_sharing_voluntary_notification_profile_for(important_entity_withdrawing_from_an_informal_contact, [attribute(entity_class, important_entity), attribute(arrangement_event, withdrew), attribute(arrangement_is_a_cybersecurity_information_sharing_arrangement, false)]).
nis2_information_sharing_voluntary_notification_profile_for(essential_entity_entering_an_unsure_arrangement, [attribute(entity_class, essential_entity), attribute(arrangement_event, entered), attribute(arrangement_is_a_cybersecurity_information_sharing_arrangement, unsure)]).
nis2_information_sharing_voluntary_notification_profile_for(essential_entity_with_an_unsure_arrangement_and_no_event, [attribute(entity_class, essential_entity), attribute(arrangement_is_a_cybersecurity_information_sharing_arrangement, unsure)]).
nis2_information_sharing_voluntary_notification_profile_for(profile_with_an_untyped_key, [attribute(entity_in_scope, true)]).
nis2_information_sharing_voluntary_notification_profile_for(empty_profile, []).

nis2_information_sharing_voluntary_notification_assess(Subject, Result) :-
    nis2_information_sharing_voluntary_notification_profile_for(Subject, Profile),
    decide_nis2_information_sharing_voluntary_notification(Profile, Result).
